cd /home/bolo/.pi/agent/sessions/--tmp-orchestra-10-boundaries-red2--/ && ls -la && python3 - <<'EOF'
import json,glob,collections,os
for f in sorted(glob.glob('/home/bolo/.pi/agent/sessions/--tmp-orchestra-10-boundaries-red2--/*.jsonl')):
    names=collections.Counter(); first=None; last=None
    editpaths=set()
    for line in open(f,encoding='utf-8'):
        try: d=json.loads(line)
        except: continue
        ts=d.get('timestamp')
        if ts:
            first=first or ts; last=ts
        # find tool calls
        def walk(o):
            if isinstance(o,dict):
                if o.get('type')=='toolCall' or 'toolName' in o:
                    n=o.get('name') or o.get('toolName')
                    if n: names[n]+=1
                    args=o.get('arguments') or o.get('input') or {}
                    if isinstance(args,str):
                        try: args=json.loads(args)
                        except: args={}
                    if isinstance(args,dict) and n in ('edit','write'):
                        p=args.get('path') or args.get('file_path')
                        if p: editpaths.add((n,p))
                for v in o.values(): walk(v)
            elif isinstance(o,list):
                for v in o: walk(v)
        walk(d)
    print(os.path.basename(f)[:60], '| first',first,'| last',last)
    print('   tools:', dict(names))
    print('   edit/write paths:', sorted(editpaths)[:12])
EOF

